 def is_square(num):
     return isqrt(num)**2 == num

 def is_palindrome(num):
     return str(num) == "".join(reversed(str(num)))

 def is_fair_and_square(num):
     return is_square(num) and is_palindrome(num) and is_palindrome(isqrt(num))

 def solve(A,B):
