 def solve_small(case):
     (N, M, A) = case
     rows = [max(row) for row in A]
     cols = [max(row[j] for row in A) for j in range(M)]
     for i in range(N):
         for j in range(M):
             if A[i][j] < min(rows[i], cols[j]):
                 return 'NO'
     return 'YES'

 def solve_large(case):
     return solve_small(case)

