             count_+=1
     return count_




 f_r = open('C.in',"r")
 n_test=int(f_r.readline().strip()) 
 f_w = open("C.out", "w")
 for i in range(n_test):
     range_ =map(int,f_r.readline().split())
     result=getNumberOfFairAndSquare(range_)
     output_str='Case #{itr}: {res}'.format(itr=(i+1),res=result)
     f_w.write(output_str+'\n')
 f_r.close()
 f_w.close()
